from pathlib import Path
import json,html
R=Path(r'D:\work\majiang-image');A=R/'assets/fx/full-game'
m=json.loads((A/'manifest.json').read_text(encoding='utf-8'));t=json.loads((A/'timelines.json').read_text(encoding='utf-8'))
data={'clips':t['clips']}
script='''const DATA=__DATA__;
const canvas=document.getElementById('stage'),ctx=canvas.getContext('2d');
const buttons=document.getElementById('clip-buttons'),status=document.getElementById('status');
const imageCache=new Map();
let active=Object.keys(DATA.clips)[0],start=performance.now(),paused=false,pauseAt=0,rate=1,ready=false;
const local=p=>p.replace('assets/fx/full-game/','');
async function loadImages(){const paths=[...new Set(Object.values(DATA.clips).flatMap(c=>c.frameFiles))];await Promise.all(paths.map(p=>new Promise((resolve,reject)=>{const im=new Image();im.onload=()=>{imageCache.set(p,im);resolve();};im.onerror=()=>reject(new Error('无法载入 '+p));im.src=local(p);})));ready=true;start=performance.now();}
function reset(){start=performance.now();pauseAt=0;paused=false;document.getElementById('pause').textContent='暂停';}
for(const [key,clip] of Object.entries(DATA.clips)){const b=document.createElement('button');b.textContent=clip.name;b.dataset.key=key;b.addEventListener('click',()=>{active=key;reset();select();});buttons.appendChild(b);}
function select(){for(const b of buttons.children){const selected=b.dataset.key===active;b.setAttribute('aria-pressed',String(selected));}const c=DATA.clips[active];document.getElementById('details').textContent=c.name+' · 4 张关键阶段 · '+c.totalDurationMs+' ms · '+(c.loop?'循环':'单次，结束隐藏');}
document.getElementById('replay').addEventListener('click',reset);
document.getElementById('pause').addEventListener('click',()=>{if(paused){start=performance.now()-pauseAt/rate;paused=false;}else{pauseAt=(performance.now()-start)*rate;paused=true;}document.getElementById('pause').textContent=paused?'播放':'暂停';});
document.getElementById('rate').addEventListener('input',e=>{const elapsed=paused?pauseAt:(performance.now()-start)*rate;rate=Number(e.target.value);start=performance.now()-elapsed/rate;document.getElementById('rate-label').textContent=rate+'×';});
for(const b of document.querySelectorAll('[data-bg]'))b.addEventListener('click',()=>{document.getElementById('stage-wrap').style.background=b.dataset.bg;});
function draw(){ctx.clearRect(0,0,512,512);if(ready){const c=DATA.clips[active],raw=paused?pauseAt:(performance.now()-start)*rate,total=c.totalDurationMs;let time=c.loop?raw%total:Math.min(raw,total);if(c.loop||raw<total){let pos=0,base=0;while(pos<c.durationMs.length-1&&time>=base+c.durationMs[pos]){base+=c.durationMs[pos];pos++;}const end=base+c.durationMs[pos],fade=Math.min(c.blendBetweenPhasesMs,c.durationMs[pos]);const hasNext=c.loop||pos<c.frameFiles.length-1;let blend=hasNext?Math.max(0,Math.min(1,(time-(end-fade))/fade)):0;let opacity=1;if(!c.loop&&time>total-c.finalFadeOutMs)opacity=Math.max(0,(total-time)/c.finalFadeOutMs);ctx.globalCompositeOperation='source-over';ctx.globalAlpha=opacity*(1-blend);ctx.drawImage(imageCache.get(c.frameFiles[pos]),0,0);if(blend>0){ctx.globalCompositeOperation='lighter';ctx.globalAlpha=opacity*blend;ctx.drawImage(imageCache.get(c.frameFiles[(pos+1)%4]),0,0);}ctx.globalAlpha=1;ctx.globalCompositeOperation='source-over';}status.textContent=(!c.loop&&raw>=total)?'播放结束，可重播':(paused?'已暂停':'关键帧预览 · 含客户端淡化补间');}requestAnimationFrame(draw);}
select();loadImages().catch(e=>status.textContent=e.message);draw();
'''.replace('__DATA__',json.dumps(data,ensure_ascii=False))
(A/'runtime-preview.js').write_text(script,encoding='utf-8')
cards=''
for item in m['assets']:
 f=item['file'].replace('assets/fx/full-game/','');cards+=f'<figure><a href="{html.escape(f)}"><img src="{html.escape(f)}" loading="lazy" alt="{html.escape(item["name"])}"></a><figcaption>{html.escape(item["name"])}</figcaption></figure>'
page='''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>麻将对局特效素材</title><style>
:root{font-family:system-ui,"Microsoft YaHei",sans-serif;color:#173f35;background:#f6efdf}body{max-width:1260px;margin:28px auto;padding:0 20px}h1{font-size:27px;margin-bottom:8px}p{line-height:1.65}a{color:#196448}button{font:inherit;border:1px solid #bca16a;background:#fff9e9;color:#173f35;border-radius:12px;padding:10px 16px;cursor:pointer}button[aria-pressed=true]{background:#196448;color:#fff9e9}.toolbar{display:flex;gap:8px;flex-wrap:wrap;margin:12px 0}.preview{display:flex;gap:28px;background:#fff9e9;border:1px solid #c8b17d;border-radius:18px;padding:22px;flex-wrap:wrap}.stage{background:#123f35;border-radius:14px;display:flex;align-items:center;justify-content:center;width:min(100%,400px);aspect-ratio:1}.stage canvas{width:100%;height:100%}.settings{flex:1;min-width:260px}.muted{font-size:14px;color:#6f6654}.grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(210px,1fr));gap:12px}figure{margin:0;border:1px solid #d9caab;border-radius:12px;background:#fff9e9;padding:10px}figure a{display:block;border-radius:8px;background:linear-gradient(90deg,#fff9e9 50%,#123f35 50%)}figure img{width:100%;height:190px;object-fit:contain}figcaption{font-size:14px;padding:8px 0 0}code{word-break:break-word}
</style><h1>麻将对局特效素材</h1><p>道家 Q 版手绘 · 8 个中文提示 · 24 张关键阶段帧 · 6 条时序 · 2 个结果装饰与 1 张空白提示底</p><p><a href="../../../index.html">返回完整游戏美术</a> · <a href="../../../docs/FX_FULL_GAME.md">接入说明</a> · <a href="manifest.json">资源清单</a> · <a href="engine/aseprite/mahjong-fx.json">Aseprite 图集 JSON</a></p><div class="preview"><div id="stage-wrap" class="stage"><canvas id="stage" width="512" height="512" aria-label="特效播放预览"></canvas></div><div class="settings"><div id="clip-buttons" class="toolbar"></div><p id="details"></p><div class="toolbar"><button id="replay">重播</button><button id="pause">暂停</button><button data-bg="#fff9e9">浅底</button><button data-bg="#123f35">深底</button></div><label>速度 <input id="rate" type="range" min="0.25" max="2" step="0.25" value="1"> <span id="rate-label">1×</span></label><p id="status" class="muted">载入本地帧…</p><p class="muted">每类为四张实际生成的阶段画。预览使用透明度补间与结束淡出；播放器不代表真实客户端已接入。各素材使用同一画布锚点，等比显示。</p></div></div><h2>全部正式素材</h2><p class="muted">点击图片查看 PNG 原文件。底色在中间分为浅底与深底，用于检查真实透明边缘。</p><div class="grid">__CARDS__</div><script src="runtime-preview.js"></script></html>'''.replace('__CARDS__',cards)
(A/'index.html').write_text(page,encoding='utf-8')
print('Wrote preview index and runtime script')
